SELECT installed_rank, version, description, installed_on, success FROM crypto_ai.flyway_schema_history ORDER BY installed_rank DESC LIMIT 15;
SELECT id, reference_signal_id, evaluation_path, evaluated_at, five_minute_signal_id, five_minute_raw_decision, five_minute_effective_decision, one_hour_signal_id, one_hour_raw_decision, one_hour_effective_decision, assessment_band, max_initial_percent, legacy_veto_result, final_result FROM crypto_ai.buy_htf_assessment_audit WHERE reference_signal_id IN (156723,159408,165412,167668,171589,176710) ORDER BY reference_signal_id, evaluated_at LIMIT 50;